define("tiny_omeroembed/plugin", [
    "exports",
    "editor_tiny/loader",
    "editor_tiny/utils",
    "tiny_omeroembed/common",
    "tiny_omeroembed/commands",
    "tiny_omeroembed/configuration",
    "tiny_omeroembed/options",
], function(exports, Loader, Utils, Common, Commands, Configuration, Options) {
    "use strict";
    Object.defineProperty(exports, "__esModule", {value: true});

    exports.default = new Promise(function(resolve) {
        Promise.all([
            Loader.getTinyMCE(),
            Commands.getSetup(),
            Utils.getPluginMetadata(Common.component, Common.pluginName),
        ]).then(function(results) {
            var tinyMCE = results[0];
            var setupCommands = results[1];
            var pluginMetadata = results[2];

            tinyMCE.PluginManager.add(Common.component + "/plugin", function(editor) {
                Options.register(editor);
                setupCommands(editor);
                return pluginMetadata;
            });

            resolve([Common.component + "/plugin", Configuration]);
        });
    });

    // Explicit return, matching core's own compiled convention (e.g.
    // tiny_h5p/plugin ends with `return _exports.default=_default,
    // _exports.default`) - RequireJS uses the factory's return value over
    // the exports-object when both are present, and editor_tiny's
    // importPluginList() (lib/editor/tiny/amd/src/editor.js) requires the
    // resolved dependency to BE the Promise directly (it does
    // `Array.isArray(pluginConfig)` after awaiting it) - without this,
    // requiring this module gives back the exports object (`.default` holds
    // the Promise) instead of the Promise itself, which importPluginList
    // silently treats as "no plugin name found" and drops from the
    // toolbar/plugin list entirely. Confirmed live: this was the exact
    // cause of the button/menu item never appearing despite is_enabled()
    // and get_plugin_configuration() both being correct server-side.
    return exports.default;
});
